style.css:
html, body {
  height: 100%;
  margin: 0;
}

body {
  background: linear-gradient(
    120deg,
    #1e3c72,
    #2a5298,
    #1e3c72
  );
  background-size: 400% 400%;
  animation: waveMotion 10s ease-in-out infinite;
}

@keyframes waveMotion {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}
